const handlerCheck = await browserjs(tabId, () => {
  const $ = window.$;
  const el = $('.jsDoSearch')[0];
  const elEvents = $._data(el, 'events');
  // Check parents
  let parent = el.parentElement;
  const parentEvents = [];
  while (parent) {
    const ev = $._data(parent, 'events');
    if (ev) parentEvents.push({ tag: parent.tagName, class: parent.className, events: Object.keys(ev) });
    parent = parent.parentElement;
  }
  return { elEvents: elEvents ? Object.keys(elEvents) : null, parentEvents };
});
